INSERT INTO `chat_message` VALUES (4978, '计算机网络基础', 1431, '刘伟', 'teacher', '@AI 超五类线是什么？', 0, '2026-08-17 23:05:31', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4979, '计算机网络基础', 1431, '刘伟', 'teacher', '@AI 超五类线是什么？', 0, '2026-08-17 23:05:31', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4980, '计算机网络基础', 1431, '刘伟', 'ai', '超五类线是双绞线的一种，属于物理层传输介质，支持最高100米内传输1000BASE-T千兆以太网，带宽为100MHz，相比五类线串扰更小，常用于局域网布线。', 1, '2026-08-17 23:05:35', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4981, '计算机网络基础', 1431, '刘伟', 'ai', '超五类线是一种双绞线电缆，属于计算机网络物理层传输介质。它支持最高100 MHz的信号频率，常用于100BASE-TX快速以太网和1000BASE-T千兆以太网，最大传输距离为100米。与五类线相比，超五类线在衰减、串扰等性能指标上更优。', 1, '2026-08-17 23:05:35', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4982, '计算机网络基础', 1431, '刘伟', 'teacher', '@冯明 你在干嘛', 1, '2026-08-17 23:06:17', 1455, NULL, NULL);
INSERT INTO `chat_message` VALUES (4983, '计算机网络基础', 1431, '刘伟', 'teacher', '111', 0, '2026-08-17 23:06:25', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4984, '计算机网络基础', 1431, '刘伟', 'teacher', '[image]/api/chat/download-file?url=%2Fuploads%2Fchat%2F%E8%AE%A1%E7%AE%97%E6%9C%BA%E7%BD%91%E7%BB%9C%E5%9F%BA%E7%A1%80%2F1786979196376_%E5%B1%8F%E5%B9%95%E6%88%AA%E5%9B%BE+2026-06-11+161900.png', 0, '2026-08-17 23:06:36', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4985, '计算机网络基础', 1431, '刘伟', 'teacher', '@AI 什么是TCP？', 0, '2026-09-09 19:06:57', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4986, '计算机网络基础', 1431, '刘伟', 'ai', 'TCP即传输控制协议，是一种面向连接的、可靠的、基于字节流的传输层协议。它在通信前需通过三次握手建立连接，通信结束后通过四次挥手释放连接。TCP使用序号和确认号实现可靠交付，通过滑动窗口和接收窗口字段进行流量控制，通过维护拥塞窗口实现拥塞控制。相对于无连接的UDP，TCP能保证数据按序、不丢失、不重复地到达对端，适用于需要高可靠性的应用。', 1, '2026-09-09 19:07:02', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4987, '计算机网络基础', 1431, '刘伟', 'teacher', '@AI 什么是计算机网络？', 0, '2026-09-09 19:07:21', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4988, '计算机网络基础', 1431, '刘伟', 'ai', '计算机网络是将分布在不同地理位置的计算机系统，通过通信设备和线路连接起来，由网络操作系统管理，实现资源共享和信息传递的系统。它的核心价值在于打破地理限制，让数据、软件和硬件资源能被多个用户共同使用。例如办公室中多台计算机通过交换机连接，共享打印机和文件服务器。', 1, '2026-09-09 19:07:23', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4989, '计算机网络基础', 1431, '刘伟', 'teacher', '@AI 你可以做什么？', 0, '2026-09-09 19:08:09', NULL, NULL, NULL);
INSERT INTO `chat_message` VALUES (4990, '计算机网络基础', 1431, '刘伟', 'ai', '- 回答本课程的知识点、概念和习题\n- 解释课程中的重点、难点和易错点\n- 分析你上传的课程图片、文件或作业\n- 根据你的学习情况推荐复习重点和学习路径\n- 总结课程章节内容并生成练习\n\n请提出你的具体问题，比如某个协议的工作原理或一道习题的解法。', 1, '2026-09-09 19:08:11', NULL, NULL, NULL);
