INSERT INTO `course_chapter` VALUES (117, 354, 1, '计算机网络与体系结构概述', '建立对计算机网络基本概念、分类和分层体系结构的整体认识，为后续各层协议学习奠定基础。', 1, 1, 0, '2026-08-17 22:16:21', '2026-08-17 22:16:21');
INSERT INTO `course_chapter` VALUES (118, 354, 2, '物理层', '学习物理层的数据通信基础、传输介质和信道复用技术，理解比特流如何在实际介质中传输。', 2, 1, 0, '2026-08-17 22:16:21', '2026-08-17 22:16:21');
INSERT INTO `course_chapter` VALUES (119, 354, 3, '数据链路层', '掌握数据链路层的成帧、差错控制、介质访问控制和以太网技术，理解相邻节点之间的可靠传输机制。', 3, 1, 0, '2026-08-17 22:16:21', '2026-08-17 22:16:21');
INSERT INTO `course_chapter` VALUES (120, 354, 4, '网络层', '学习 IP 地址、子网划分、路由算法和网络层协议，理解数据包如何跨越多个网络到达目的主机。', 4, 1, 0, '2026-08-17 22:16:21', '2026-08-17 22:16:21');
INSERT INTO `course_chapter` VALUES (121, 354, 5, '传输层', '掌握传输层端到端通信机制，重点理解 UDP 的简单传输和 TCP 的可靠传输、拥塞控制与连接管理。', 5, 1, 0, '2026-08-17 22:16:21', '2026-08-17 22:16:21');
INSERT INTO `course_chapter` VALUES (122, 354, 6, '应用层', '学习 HTTP、DNS、电子邮件和文件传输等典型应用层协议，理解网络应用如何利用传输层服务完成用户任务。', 6, 1, 0, '2026-08-17 22:16:21', '2026-08-17 22:16:21');
INSERT INTO `course_chapter` VALUES (123, 354, 7, '网络安全与新技术', '了解网络安全基本威胁与加密技术、防火墙与入侵检测，以及 IPv6 等下一代网络技术。', 7, 1, 0, '2026-08-17 22:16:21', '2026-08-17 22:16:21');
INSERT INTO `course_chapter` VALUES (124, 358, 1, '英语语音、词汇与基本句型', '建立英语发音与词汇基础，掌握基本句子结构。', 1, 1, 0, '2026-09-12 16:58:59', '2026-09-12 16:58:59');
INSERT INTO `course_chapter` VALUES (125, 358, 2, '英语语法体系与复杂结构', '系统掌握时态、语态、从句和非谓语动词等复杂语法。', 2, 1, 0, '2026-09-12 16:58:59', '2026-09-12 16:58:59');
INSERT INTO `course_chapter` VALUES (126, 358, 3, '段落阅读与语篇分析', '从段落和语篇层面提升阅读理解与分析能力。', 3, 1, 0, '2026-09-12 16:58:59', '2026-09-12 16:58:59');
INSERT INTO `course_chapter` VALUES (127, 358, 4, '学术写作基础', '掌握学术段落、论证方法和摘要引言结论的写作规范。', 4, 1, 0, '2026-09-12 16:58:59', '2026-09-12 16:58:59');
INSERT INTO `course_chapter` VALUES (128, 358, 5, '学术论文写作与引用规范', '学习文献检索、评估、引用格式及避免抄袭的策略。', 5, 1, 0, '2026-09-12 16:58:59', '2026-09-12 16:58:59');
INSERT INTO `course_chapter` VALUES (129, 358, 6, '跨文化交际与学术演讲', '培养跨文化交际意识，提升学术演讲与辩论能力。', 6, 1, 0, '2026-09-12 16:58:59', '2026-09-12 16:58:59');
INSERT INTO `course_chapter` VALUES (130, 359, 1, '函数、极限与连续', '从函数概念出发，建立极限与连续的基础，为微积分学习铺路。', 1, 1, 1, '2026-09-20 17:47:48', '2026-09-20 17:48:54');
INSERT INTO `course_chapter` VALUES (131, 359, 2, '一元函数微分学', '围绕导数、微分中值定理与泰勒展开，掌握函数局部与整体性质分析。', 2, 1, 1, '2026-09-20 17:47:48', '2026-09-20 17:48:58');
INSERT INTO `course_chapter` VALUES (132, 359, 3, '一元函数积分学', '从原函数与定积分出发，理解微积分基本定理并掌握积分应用。', 3, 1, 1, '2026-09-20 17:47:48', '2026-09-20 17:49:00');
INSERT INTO `course_chapter` VALUES (133, 359, 4, '多元函数微积分', '进入多元函数、偏导数、全微分与二重积分，建立高维分析基础。', 4, 1, 1, '2026-09-20 17:47:48', '2026-09-20 17:49:02');
INSERT INTO `course_chapter` VALUES (134, 359, 5, '微分方程', '学习一阶与二阶常微分方程，并用微分方程描述动态系统。', 5, 1, 1, '2026-09-20 17:47:48', '2026-09-20 17:49:04');
INSERT INTO `course_chapter` VALUES (135, 359, 6, '线性代数', '掌握矩阵、向量空间、线性变换与特征值，理解线性结构。', 6, 1, 1, '2026-09-20 17:47:48', '2026-09-20 17:49:06');
INSERT INTO `course_chapter` VALUES (136, 359, 7, '概率论与数理统计', '从随机事件、随机变量到参数估计与假设检验，建立数据推断思维。', 7, 1, 1, '2026-09-20 17:47:48', '2026-09-20 17:49:08');
INSERT INTO `course_chapter` VALUES (137, 359, 1, '认识数与数感', '从生活中的物品出发，认识0到100的数，学会数数、读写、比大小和简单分解。', 1, 1, 1, '2026-09-20 22:21:15', '2026-09-20 22:34:35');
INSERT INTO `course_chapter` VALUES (138, 359, 2, '加减法基础', '在20以内学习加法和减法，理解意义，掌握凑十法、破十法和简单竖式。', 2, 1, 1, '2026-09-20 22:21:15', '2026-09-20 22:34:37');
INSERT INTO `course_chapter` VALUES (139, 359, 3, '乘除法初步', '从相同加数相加出发，认识乘法、口诀和除法，理解乘除之间的简单关系。', 3, 1, 1, '2026-09-20 22:21:15', '2026-09-20 22:34:40');
INSERT INTO `course_chapter` VALUES (140, 359, 4, '分数与小数初步', '借助分饼、分水果和钱币，认识分数和小数，理解它们表示部分与整体的关系。', 4, 1, 1, '2026-09-20 22:21:15', '2026-09-20 22:34:52');
INSERT INTO `course_chapter` VALUES (141, 359, 5, '图形与测量', '认识常见平面图形，学习长度、周长和面积的初步知识，并用简单工具测量。', 5, 1, 1, '2026-09-20 22:21:15', '2026-09-20 22:34:54');
INSERT INTO `course_chapter` VALUES (142, 359, 6, '数据与规律', '学习分类、统计表和简单条形图，发现数字与图形中的规律，培养观察和表达能力。', 6, 1, 1, '2026-09-20 22:21:15', '2026-09-20 22:34:56');
INSERT INTO `course_chapter` VALUES (143, 359, 1, '实分析基础与极限理论', '从实数完备性到一致收敛，建立严格极限语言与证明能力。', 1, 1, 1, '2026-09-20 22:35:58', '2026-09-20 22:50:15');
INSERT INTO `course_chapter` VALUES (144, 359, 2, '线性算子与矩阵分析', '研究线性空间、基变换、谱与奇异值分解，连接理论与数值计算。', 2, 1, 1, '2026-09-20 22:35:58', '2026-09-20 22:50:17');
INSERT INTO `course_chapter` VALUES (145, 359, 3, '概率论、随机过程与统计推断', '构建概率空间、条件期望、马尔可夫链与统计推断的统一框架。', 3, 1, 1, '2026-09-20 22:35:58', '2026-09-20 22:50:19');
INSERT INTO `course_chapter` VALUES (146, 359, 4, '数值分析与科学计算', '面向科学计算，覆盖误差、矩阵分解、插值、积分与微分方程数值解。', 4, 1, 1, '2026-09-20 22:35:58', '2026-09-20 22:50:21');
INSERT INTO `course_chapter` VALUES (147, 359, 5, '优化、变分与数学建模', '进入凸优化、变分法与最优控制，并以综合建模与高性能实现收束。', 5, 1, 1, '2026-09-20 22:35:58', '2026-09-20 22:50:23');
INSERT INTO `course_chapter` VALUES (148, 359, 1, '极限与连续性的严格理论', '从数列极限的 ε-N 语言出发，深入理解函数极限、连续性及一致连续，为后续分析打下坚实基础。', 1, 1, 0, '2026-09-20 22:51:36', '2026-09-20 22:51:36');
INSERT INTO `course_chapter` VALUES (149, 359, 2, '矩阵分析与特征值分解', '深入矩阵的特征值、奇异值分解与范数理论，掌握矩阵分析在数据降维和数值稳定性中的核心应用。', 2, 1, 0, '2026-09-20 22:51:36', '2026-09-20 22:51:36');
INSERT INTO `course_chapter` VALUES (150, 359, 3, '概率论极限定理与随机过程', '学习大数定律、中心极限定理及马尔可夫链，掌握随机模拟与蒙特卡洛方法，理解随机现象的极限规律。', 3, 1, 0, '2026-09-20 22:51:36', '2026-09-20 22:51:36');
INSERT INTO `course_chapter` VALUES (151, 359, 4, '数值优化与迭代方法', '掌握梯度下降、牛顿法及凸优化理论，分析收敛速度与对偶问题，解决实际优化任务。', 4, 1, 0, '2026-09-20 22:51:36', '2026-09-20 22:51:36');
INSERT INTO `course_chapter` VALUES (152, 357, 1, '传感器技术概述', '介绍传感器的定义、分类、系统组成及发展趋势，建立传感器技术的基本概念框架。', 1, 1, 0, '2026-09-21 13:11:39', '2026-09-21 13:11:39');
INSERT INTO `course_chapter` VALUES (153, 357, 2, '传感器的基本特性与标定', '讨论传感器的静态特性、动态特性、标定方法与误差分析，为后续具体传感器学习奠定基础。', 2, 1, 0, '2026-09-21 13:11:39', '2026-09-21 13:11:39');
INSERT INTO `course_chapter` VALUES (154, 357, 3, '电阻式传感器', '学习电位器式、应变式、压阻式电阻传感器的工作原理、特性及应用电路。', 3, 1, 0, '2026-09-21 13:11:39', '2026-09-21 13:11:39');
INSERT INTO `course_chapter` VALUES (155, 357, 4, '电容式与电感式传感器', '学习电容式和电感式传感器的工作原理、测量电路及典型应用。', 4, 1, 0, '2026-09-21 13:11:39', '2026-09-21 13:11:39');
INSERT INTO `course_chapter` VALUES (156, 357, 5, '压电式、磁电式与热电式传感器', '学习压电式、磁电式和热电式传感器的工作原理、特性及应用。', 5, 1, 0, '2026-09-21 13:11:39', '2026-09-21 13:11:39');
INSERT INTO `course_chapter` VALUES (157, 357, 6, '光电式与新型传感器及综合应用', '学习光电式、光纤、红外及智能传感器，并综合应用传感器技术解决实际问题。', 6, 1, 0, '2026-09-21 13:11:39', '2026-09-21 13:11:39');
