INSERT INTO `exam_homework` VALUES (10, 'exam', '网络技术考试', '第一次网络技术考试', 354, 46, 122, '2026-08-17 22:51:00', '2026-08-17 22:55:00', 60, 100, 60, 'scheduled', '2026-08-17 22:51:00', 'ai-range', '[\"single_choice\", \"multiple_choice\", \"true_false\"]', 'hard', 5, 2, 0, 2, '2026-08-17 22:51:24', '2026-09-20 10:10:23');
INSERT INTO `exam_homework` VALUES (11, 'homework', '英语测试1', '', 358, 47, 127, '2026-09-20 15:05:00', '2026-09-20 15:10:00', 60, 100, 60, 'immediate', NULL, 'ai-range', '[\"single_choice\", \"multiple_choice\", \"true_false\"]', 'medium', 20, 2, 0, 2, '2026-09-20 15:06:18', '2026-09-20 15:10:15');
INSERT INTO `exam_question` VALUES (134, 10, 1, 'multiple_choice', '基于计算机网络体系结构、地址规划与交换技术，下列有关说法正确的有（ ）。', '[\"A. 在TCP/IP模型中，访问网页时浏览器使用HTTP协议，传输层使用TCP协议，网际层使用IP协议。\", \"B. 以太网交换机根据MAC地址表转发帧，每个端口是独立冲突域；划分VLAN后可以隔离广播域，但不同VLAN间通信必须经过三层设备。\", \"C. 一条链路带宽为100 Mbps，实际吞吐量可能只有80 Mbps，这是因为带宽是理论能力，吞吐量受网络拥塞、设备性能等因素影响。\", \"D. IPv4地址192.168.1.10是一个C类私有地址，若其所在网络使用子网掩码255.255.255.192，则可划分出2个子网，每个子网可用主机数为62。\"]', 'A,B,C', 20, '困难', '2026-08-17 22:51:24');
INSERT INTO `exam_question` VALUES (135, 10, 2, 'single_choice', '某企业网络中，财务部与研发部分别划入VLAN 10和VLAN 20，IP地址块分别为192.168.10.0/26和192.168.10.64/26。财务部主机甲IP为192.168.10.20/26，研发部主机乙IP为192.168.10.70/26，二者通过一台二层交换机连接，且交换机上配置了VLAN隔离。网络中的三层设备配置了VLAN 10和VLAN 20的网关地址，分别为192.168.10.1和192.168.10.65。主机甲向主机乙发送一个IP数据报。以下说法正确的是（ ）', '[\"A. 主机甲将目的MAC地址设置为主机乙的MAC地址，交换机根据MAC地址表将其从乙所在端口转发出去\", \"B. 主机甲将目的MAC地址设置为默认网关192.168.10.1的MAC地址，并需要三层设备将数据报从VLAN 10路由到VLAN 20\", \"C. 因为主机甲和主机乙的IP地址处于同一个/24网络，所以主机甲会直接通过ARP广播获得主机乙的MAC地址并封装帧\", \"D. 交换机收到该帧后，会在VLAN 10内除接收端口外的所有端口泛洪，从而主机乙能够收到该帧\"]', 'B', 20, '困难', '2026-08-17 22:51:24');
INSERT INTO `exam_question` VALUES (136, 10, 3, 'true_false', '在OSI参考模型中，物理层负责比特流传输，数据链路层负责相邻节点可靠传输，网络层负责主机间路由选择；而TCP/IP模型中的网际层对应OSI的物理层和数据链路层，传输层对应OSI的网络层。因此，以太网交换机工作在TCP/IP模型的网际层。', '[\"正确\", \"错误\"]', '错误', 20, '困难', '2026-08-17 22:51:24');
INSERT INTO `exam_question` VALUES (137, 10, 4, 'true_false', '网络管理员将192.168.1.0/24网络划分为4个等长子网，需要借用2位主机位，子网掩码变为255.255.255.192，每个子网包含64个地址，其中可用主机地址为62个；由于该网络是C类私有地址，所以子网划分后各子网之间可以直接通过二层交换机进行通信。', '[\"正确\", \"错误\"]', '错误', 20, '困难', '2026-08-17 22:51:24');
INSERT INTO `exam_question` VALUES (138, 10, 5, 'true_false', '交换机每个端口是独立冲突域，但默认属于同一广播域。虚拟局域网（VLAN）技术可以将交换机端口逻辑分组，隔离广播域，减少广播流量并提高安全性；不同VLAN之间必须经过三层设备才能通信。家庭路由器连接宽带属于网络边缘设备，其上游的运营商路由器属于网络核心。', '[\"正确\", \"错误\"]', '正确', 20, '困难', '2026-08-17 22:51:24');
INSERT INTO `exam_question` VALUES (139, 11, 1, 'multiple_choice', '根据材料，下列对英语时态体系的理解正确的有：', '[\"英语时态由“时间”和“体”两个维度结合构成，共16种\", \"现在完成进行时强调动作的持续，如 I have been studying English for three years.\", \"一般时、进行时、完成时和完成进行时都可与现在、过去、将来结合\", \"英语时态只有现在、过去、将来三种，不涉及“体”的概念\"]', 'ABC', 5, 'medium', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (140, 11, 2, 'multiple_choice', '根据材料，下列关于被动语态与情态动词的说法正确的有：', '[\"被动语态由 be + 过去分词构成，强调动作承受者或无需指出执行者\", \"若要指出动作执行者，可用 by 引出，如 The novel was written by Dickens.\", \"情态动词后接动词原形，可表示能力、许可、义务、推测\", \"It might rain tomorrow. 中的 might 表示义务\"]', 'ABC', 5, 'medium', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (141, 11, 3, 'multiple_choice', '根据材料，下列对英语五种基本句型及句子成分的分析正确的有：', '[\"He gave me a book. 属于 S+V+IO+DO 结构\", \"They elected him president. 中 president 是宾语补足语\", \"The girl in red sings beautifully. 中 in red 是定语，beautifully 是状语\", \"She smiled. 属于 S+V+O 结构\"]', 'ABC', 5, 'medium', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (142, 11, 4, 'multiple_choice', '根据材料，下列关于语音知识的表述正确的有：', '[\"元音发音时气流不受阻碍，辅音发音时受到唇、齿、舌等器官的阻碍\", \"清辅音声带不振动，浊辅音声带振动，如 /p/ 是清辅音，/b/ 是浊辅音\", \"ship /ʃɪp/ 与 sheep /ʃiːp/ 构成最小对立对，仅元音不同\", \"国际音标与拼写一一对应，同一音素在不同单词中拼写相同\"]', 'ABC', 5, 'medium', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (143, 11, 5, 'multiple_choice', '根据材料，下列关于词汇学习与阅读策略的说法正确的有：', '[\"前缀改变词义，后缀改变词性，如 un- 和 -ness 可构成 unhappiness\", \"应通过语境记忆词汇，注意搭配，如 make a decision 而非 do a decision\", \"间隔重复可利用遗忘曲线，在1天、3天、7天、14天后复习\", \"阅读时只需识别 however、therefore 等逻辑关系词，无需关注段落模式\"]', 'ABC', 5, 'medium', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (144, 11, 6, 'multiple_choice', '根据课程材料，下列关于英语语言知识的表述，正确的有哪些？', '[\"现在完成进行时强调动作的持续，如“I have been studying English for three years.”\", \"在“They elected him president.”中，president是宾语补足语。\", \"清辅音声带振动，浊辅音声带不振动。\", \"前缀改变词性，后缀改变词义。\"]', 'AB', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (145, 11, 7, 'single_choice', 'The bridge ______ by workers last year.', '[\"A. built\", \"B. was built\", \"C. is built\", \"D. has built\"]', 'B', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (146, 11, 8, 'single_choice', '句子“They elected him president.”属于哪一种基本句型？', '[\"A. S+V+O\", \"B. S+V+IO+DO\", \"C. S+V+O+C\", \"D. S+V+P\"]', 'C', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (147, 11, 9, 'single_choice', '下列哪组词仅元音不同，可作为最小对立对帮助辨音？', '[\"A. ship /ʃɪp/ 与 sheep /ʃiːp/\", \"B. /p/ 与 /b/\", \"C. cat /kæt/ 与 cap /kæp/\", \"D. take /teɪk/ 与 make /meɪk/\"]', 'A', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (148, 11, 10, 'single_choice', '根据构词法，下列表述正确的是？', '[\"A. un- 改变词义，-ness 改变词性\", \"B. un- 改变词性，-ness 改变词义\", \"C. un- 和 -ness 都只改变词性\", \"D. un- 和 -ness 都只改变词义\"]', 'A', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (149, 11, 11, 'single_choice', '在“The plan was expensive. However, it was effective.”中，However 表示什么逻辑关系？', '[\"A. 结果\", \"B. 转折\", \"C. 递进\", \"D. 举例\"]', 'B', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (150, 11, 12, 'single_choice', '在句子“They elected him president.”中，president 在句中充当的成分是：', '[\"主语补足语\", \"宾语补足语\", \"定语\", \"状语\"]', 'B', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (151, 11, 13, 'true_false', '在句子 \'They elected him president.\' 中，president 是宾语补足语，用于补充说明宾语 him。', '[\"正确\", \"错误\"]', '正确', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (152, 11, 14, 'true_false', '句子 \'He gave me a book.\' 属于 S+V+IO+DO 结构，其中 me 是直接宾语，a book 是间接宾语。', '[\"正确\", \"错误\"]', '错误', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (153, 11, 15, 'true_false', '在被动语态中，若需指出执行者用 by 引出；情态动词后接动词原形。因此 \'The novel was written by Dickens.\' 中 by Dickens 指出执行者，\'You must finish the report today.\' 中 must 后接动词原形 finish。', '[\"正确\", \"错误\"]', '正确', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (154, 11, 16, 'true_false', '前缀通常改变词义，后缀通常改变词性；因此 unhappiness 可视为由 un- + happy + -ness 构成。', '[\"正确\", \"错误\"]', '正确', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (155, 11, 17, 'true_false', '在 \'The plan was expensive. However, it was effective.\' 中，However 表示递进关系。', '[\"正确\", \"错误\"]', '错误', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (156, 11, 18, 'true_false', '在句子 \'They elected him president.\' 中，\'president\' 是宾语补足语，用来补充说明宾语 \'him\'。', '[\"正确\", \"错误\"]', '正确', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (157, 11, 19, 'true_false', '情态动词后接动词原形，因此 \'The problem can solved easily.\' 是正确的被动语态表达。', '[\"正确\", \"错误\"]', '错误', 5, '中等', '2026-09-20 15:06:18');
INSERT INTO `exam_question` VALUES (158, 11, 20, 'true_false', '英语中，/i:/ 和 /ɪ/ 是同一个音素的不同变体，所以 \'ship\' 和 \'sheep\' 发音相同。', '[\"正确\", \"错误\"]', '错误', 5, '中等', '2026-09-20 15:06:18');
