INSERT INTO `quiz_answer` VALUES (439, 186, 9, '判断', '计算机网络基础', '网络核心由主机和服务器组成，负责数据的高速转发。', NULL, '错误', '错误*', 1, 0, 1, '2026-09-08 18:42:31', 0);
INSERT INTO `quiz_answer` VALUES (440, 186, 10, '判断', '计算机网络基础', 'OSI模型理论完整但实现复杂，TCP/IP模型简单实用。', NULL, '正确', '正确*', 1, 0, 1, '2026-09-08 18:42:31', 0);
INSERT INTO `quiz_answer` VALUES (441, 186, 11, '解析', '计算机网络基础', '请解释带宽与吞吐量的区别。', NULL, '不会', '带宽是单位时间内能传输的最大数据量，是链路的理论能力；吞吐量是实际测得的有效传输速率，受网络拥塞、设备性能等因素影响，是实际表现。', -1, 1, 0, '2026-09-08 18:42:31', 0);
INSERT INTO `quiz_answer` VALUES (442, 186, 12, '解析', '计算机网络基础', '请按从下到上的顺序写出OSI参考模型的七层名称。', NULL, '不会', '物理层、数据链路层、网络层、传输层、会话层、表示层、应用层。', -1, 0, 0, '2026-09-08 18:42:31', 0);
INSERT INTO `quiz_answer` VALUES (443, 186, 13, '解析', '计算机网络基础', '时延由哪几部分组成？发送时延和传播时延分别如何计算？', NULL, '不会', '时延由发送时延、传播时延、处理时延和排队时延四部分组成。发送时延=数据长度/带宽；传播时延=链路长度/信号传播速率。', -1, 0, 0, '2026-09-08 18:42:31', 0);
INSERT INTO `quiz_answer` VALUES (444, 186, 14, '填空', '计算机网络基础', '带宽指单位时间内能传输的____，单位为比特每秒。', NULL, '不会', '最大数据量', -1, 0, 0, '2026-09-08 18:42:31', 0);
