INSERT INTO `quiz_answer` VALUES (516, 191, 11, '解析', '计算机网络基础', '简述计算机网络的定义。', NULL, '不会', '计算机网络是指将分布在不同地理位置的计算机系统通过通信设备和线路连接起来，由网络操作系统管理，实现资源共享和信息传递的系统。', -1, 1, 0, '2026-09-09 18:59:32', 0);
INSERT INTO `quiz_answer` VALUES (517, 191, 12, '解析', '计算机网络基础', '时延由哪四部分组成？请分别简要说明。', NULL, '不会', '时延由发送时延、传播时延、处理时延和排队时延四部分组成。发送时延是数据从发送端进入链路所需的时间；传播时延是信号在链路上传播所需的时间；处理时延是路由器或主机处理数据所需的时间；排队时延是数据在队列中等待转发的时间。', -1, 0, 0, '2026-09-09 18:59:32', 0);
