INSERT INTO `quiz_answer` VALUES (576, 196, 11, '解析', '计算机网络基础', '请简述计算机网络的定义。', NULL, '计算机网络是指将地理位置不同、具有独立功能的多台计算机及其外部设备，通过通信线路和通信设备连接起来，在网络操作系统、网络管理软件及网络通信协议的管理和协调下，实现资源共享和信息交换的计算机系统。\n简单来说，计算机网络的核心目的有两点：信息传递和资源共享（如共享打印机、软件和数据等）。', '计算机网络是指将分布在不同地理位置的计算机系统通过通信设备和线路连接起来，由网络操作系统管理，实现资源共享和信息传递的系统。', 0, 0, 0, '2026-09-09 22:30:20', 0);
