INSERT INTO `quiz_answer` VALUES (621, 201, 11, '解析', '英语', '请解释前缀和后缀在构词中的作用，并举例说明。', NULL, '不会', '前缀改变词义，后缀改变词性。例如：unhappiness 由 un- + happy + -ness 构成。', -1, 2, 0, '2026-09-12 21:05:51', 0);
INSERT INTO `quiz_answer` VALUES (622, 201, 12, '解析', '英语', '请说明如何利用语境记忆和词汇网络提高词汇学习效率。', NULL, '不会', '应通过语境记忆，使用语义地图将相关词归类，如环境类 pollution、recycle、sustainable；注意搭配，如 make a decision 而非 do a decision，阅读时记录 take measures。', -1, 0, 0, '2026-09-12 21:05:51', 0);
INSERT INTO `quiz_answer` VALUES (623, 201, 13, '解析', '英语', '请写出英语五种基本句型及其符号含义。', NULL, '不会', '五种基本句型为 S+V、S+V+O、S+V+P、S+V+IO+DO、S+V+O+C。S 为主语，V 为谓语，O 为宾语，P 为表语，IO 为间接宾语，DO 为直接宾语，C 为补语。', -1, 0, 0, '2026-09-12 21:05:51', 0);
