INSERT INTO `quiz_answer` VALUES (633, 203, 8, '判断', '英语', '在构词法中，前缀改变词义，后缀改变词性。', NULL, '正确', '正确*', 1, 2, 1, '2026-09-20 10:16:05', 0);
INSERT INTO `quiz_answer` VALUES (634, 203, 9, '判断', '英语', '英语是重音计时语言，重读音节突出，非重读音节弱化。', NULL, '错误', '正确*', 0, 0, 1, '2026-09-20 10:16:05', 0);
INSERT INTO `quiz_answer` VALUES (635, 203, 10, '判断', '英语', '句子“He gave me a book.”的基本句型是 S+V+O+C。', NULL, '正确', '错误*', 0, 0, 1, '2026-09-20 10:16:05', 0);
INSERT INTO `quiz_answer` VALUES (636, 203, 11, '解析', '英语', '根据词根与词缀的相关知识，解释前缀和后缀在构词中的不同作用，并写出单词 unhappiness 的构成方式（写出各部分并说明其作用）。', NULL, '不会', '前缀改变词义，后缀改变词性。unhappiness 由 un- + happy + -ness 构成：其中 un- 是前缀，改变词义，表示“不”；happy 是词根（核心意义单位），表示“快乐”；-ness 是后缀，改变词性，使形容词 happy 变成名词，表示“……的状态”，整个词意为“不快乐、不幸”。', -1, 1, 0, '2026-09-20 10:16:05', 0);
INSERT INTO `quiz_answer` VALUES (637, 203, 12, '解析', '英语', '英语音素分为元音和辅音，辅音又可分为清辅音和浊辅音。请指出 /i:/、/æ/、/p/、/b/、/θ/ 中哪些是元音、哪些是辅音，并说明清辅音与浊辅音的区别，判断 /p/ 和 /b/ 分别属于哪一类。', NULL, '不会', '/i:/ 和 /æ/ 是元音，因为发音时气流不受阻碍；/p/、/b/、/θ/ 是辅音，因为发音时受到唇、齿、舌等器官的阻碍。清辅音声带不振动，浊辅音声带振动。/p/ 是清辅音（声带不振动），/b/ 是浊辅音（声带振动）。', -1, 0, 0, '2026-09-20 10:16:05', 0);
INSERT INTO `quiz_answer` VALUES (638, 203, 13, '解析', '英语', '英语有五种基本句型。请指出 She smiled. 和 He gave me a book. 分别属于哪种基本句型，并结合句中的成分加以解析。', NULL, '不会', 'She smiled. 属于 S+V（主语+谓语）句型：She 是主语，smiled 是谓语，句子没有宾语。He gave me a book. 属于 S+V+IO+DO（主语+谓语+间接宾语+直接宾语）句型：He 是主语，gave 是谓语，me 是间接宾语，a book 是直接宾语。', -1, 0, 0, '2026-09-20 10:16:05', 0);
INSERT INTO `quiz_answer` VALUES (639, 203, 14, '填空', '英语', '根据词缀知识，前缀改变词义，后缀改变______。', NULL, '不会', '词性', -1, 0, 0, '2026-09-20 10:16:05', 0);
