INSERT INTO `quiz_answer` VALUES (651, 204, 11, '解析', '英语', '根据词根与词缀的相关知识，解释前缀和后缀在构词中的不同作用，并写出单词 unhappiness 的构成方式（写出各部分并说明其作用）。', NULL, '不会', '前缀改变词义，后缀改变词性。unhappiness 由 un- + happy + -ness 构成：其中 un- 是前缀，改变词义，表示“不”；happy 是词根（核心意义单位），表示“快乐”；-ness 是后缀，改变词性，使形容词 happy 变成名词，表示“……的状态”，整个词意为“不快乐、不幸”。', -1, 1, 0, '2026-09-20 10:27:40', 0);
INSERT INTO `quiz_answer` VALUES (652, 204, 12, '解析', '英语', '英语音素分为元音和辅音，辅音又可分为清辅音和浊辅音。请指出 /i:/、/æ/、/p/、/b/、/θ/ 中哪些是元音、哪些是辅音，并说明清辅音与浊辅音的区别，判断 /p/ 和 /b/ 分别属于哪一类。', NULL, '不会', '/i:/ 和 /æ/ 是元音，因为发音时气流不受阻碍；/p/、/b/、/θ/ 是辅音，因为发音时受到唇、齿、舌等器官的阻碍。清辅音声带不振动，浊辅音声带振动。/p/ 是清辅音（声带不振动），/b/ 是浊辅音（声带振动）。', -1, 0, 0, '2026-09-20 10:27:40', 0);
INSERT INTO `quiz_answer` VALUES (653, 204, 13, '解析', '英语', '英语有五种基本句型。请指出 She smiled. 和 He gave me a book. 分别属于哪种基本句型，并结合句中的成分加以解析。', NULL, '不会', 'She smiled. 属于 S+V（主语+谓语）句型：She 是主语，smiled 是谓语，句子没有宾语。He gave me a book. 属于 S+V+IO+DO（主语+谓语+间接宾语+直接宾语）句型：He 是主语，gave 是谓语，me 是间接宾语，a book 是直接宾语。', -1, 0, 0, '2026-09-20 10:27:40', 0);
INSERT INTO `quiz_answer` VALUES (654, 204, 14, '填空', '英语', '根据词缀知识，前缀改变词义，后缀改变______。', NULL, '不会', '词性', -1, 0, 0, '2026-09-20 10:27:40', 0);
INSERT INTO `quiz_answer` VALUES (655, 204, 15, '填空', '英语', '英语音素分为元音和辅音；发音时声带振动的辅音称为______。', NULL, '不会', '浊辅音', -1, 0, 0, '2026-09-20 10:27:40', 0);
