INSERT INTO `quiz_session` VALUES (212, 1532, '英语', 358, 1, '[124]', '专业', 11, 15, 3, 0, 12, 62, '{\"专注耐力\": 0, \"专业学习力\": 0, \"信息检索力\": 0, \"判断决策力\": 0, \"自律执行力\": 0, \"逻辑思维力\": 0}', '[\"本次作答有效信息不足，暂不形成能力结论\"]', '[\"正确率较低、跳过较多或作答过快，建议认真作答后再次测评\"]', '本次共 15 题，跳过 12 题，作答 62 秒。系统暂不根据本次结果调整难度，建议先回看章节内容，再认真完成一次测评。', '[\"回看本次错题和对应章节\", \"认真作答下一次测评\"]', 'evaluated', '2026-09-20 13:28:47');
INSERT INTO `quiz_session` VALUES (213, 1532, '英语', 358, 1, '[124]', '专业', 12, 15, 10, 5, 5, 10, '{\"专注耐力\": 0, \"专业学习力\": 0, \"信息检索力\": 0, \"判断决策力\": 0, \"自律执行力\": 0, \"逻辑思维力\": 0}', '[\"本次作答有效信息不足，暂不形成能力结论\"]', '[\"正确率较低、跳过较多或作答过快，建议认真作答后再次测评\"]', '本次共 15 题，跳过 5 题，作答 10 秒。系统暂不根据本次结果调整难度，建议先回看章节内容，再认真完成一次测评。', '[\"回看本次错题和对应章节\", \"认真作答下一次测评\"]', 'evaluated', '2026-09-20 13:42:39');
INSERT INTO `quiz_session` VALUES (214, 1532, '英语', 358, 1, '[124]', '专业', 13, 15, 10, 5, 5, 41, '{\"专注耐力\": 1, \"专业学习力\": 1, \"信息检索力\": 1, \"判断决策力\": 1, \"自律执行力\": 1, \"逻辑思维力\": 1}', '[]', '[\"正确率极低，基础知识掌握薄弱\", \"大量题目跳过，长题直接放弃\", \"作答时间过短，存在明显猜测\", \"词缀、语音、基本句型等专业知识混淆\"]', '建议从基础语法、语音和词缀知识开始系统补强，先保证作答完整度，再逐步提升准确率与速度。', '[\"第1周：每天复习词缀知识，掌握前缀改变词义、后缀改变词性，练习10个派生词分析。\", \"第2周：每天复习音标与语音，区分元音/辅音、清辅音/浊辅音及长短元音。\", \"第3周：每天练习五种基本句型，重点区分S+V+O+O与S+V+O+C。\", \"第4周：按1天、3天、7天、14天进行间隔重复，结合语义地图整理词汇。\", \"每周进行一次15题限时测验，要求全部作答，减少跳过并记录错因。\"]', 'evaluated', '2026-09-20 14:06:06');
INSERT INTO `quiz_session` VALUES (215, 1532, '英语', 358, 1, '[124]', '专业', 14, 15, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-09-20 14:14:48');
INSERT INTO `quiz_session` VALUES (216, 1532, '英语', 358, 1, '[124]', '专业', 15, 15, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-09-20 14:22:32');
INSERT INTO `quiz_session` VALUES (217, 1532, '英语', 358, 1, '[124]', '专业', 16, 15, 10, 5, 5, 16, '{\"专注耐力\": 1, \"专业学习力\": 3, \"信息检索力\": 2, \"判断决策力\": 3, \"自律执行力\": 1, \"逻辑思维力\": 2}', '[\"能正确完成部分基础客观题：语境记忆、间隔重复、ship/sheep音标区别、S+V+IO+DO句型、前缀改变词义/后缀改变词性。\", \"对少量核心概念有初步识别能力，但稳定性不足。\"]', '[\"基础概念混淆严重：前缀/后缀作用、清浊辅音、英语重音计时、基本句型判断均出现错误。\", \"5道开放性简答题全部跳过或回答“不会”，缺乏知识迁移、组织表达与综合应用能力。\", \"总耗时16秒、多题0秒作答，存在明显猜测、放弃和未认真思考的倾向。\", \"正确率趋势为0%/0%/0%，未形成稳定掌握与复习闭环。\", \"自律执行与专注耐力不足，跳过题目较多。\", \"信息检索与章节内容对应能力弱，部分章节题判断错误。\"]', '先停止快速刷题，按词缀、音标、句型三大基础模块重建知识框架；每道题必须写出判断依据，开放题先列要点再作答。采用1天、3天、7天、14天间隔复习，错题当天重做并口述规则。每天限时但不低于10分钟，重点训练专注度和完整作答习惯。', '[\"Day1：整理前缀表义、后缀变词性规则，重点写unhappiness=un-+happy+-ness，并各造5个词例。\", \"Day2：复习元音、辅音、清辅音、浊辅音，重点对比/p/与/b/、/ʃɪp/与/ʃiːp/，跟读并录音纠音。\", \"Day3：复习五种基本句型，分别写5个例句并标注S、V、O、IO、DO、C，重点纠正He gave me a book。\", \"Day4：复习重音计时与弱化规则，朗读10个短语和5个句子，标出重读音节。\", \"Day5：用语义地图整理20个相关词，练习语境记忆，并完成10道章节客观题。\", \"Day6：综合练习20题，限时但不少于10分钟，逐题写理由，错题归类。\", \"Day7：重写Q11-Q15开放题，对照标准答案订正，并用1/3/7/14间隔重复安排下周复习。\"]', 'evaluated', '2026-09-20 14:28:03');
INSERT INTO `quiz_session` VALUES (218, 1532, '数学', 359, 1, '[137]', '专业', 17, 15, 11, 6, 4, 75, '{\"专注耐力\": 1, \"专业学习力\": 1, \"信息检索力\": 1, \"判断决策力\": 2, \"自律执行力\": 1, \"逻辑思维力\": 2}', '[\"能正确完成极少数基础题，如7>4、5的后一个数是6、数轴越靠右数越大等\", \"Q15中前两个空能填出3和4，显示对凑十和数序有初步痕迹\"]', '[\"10个10个数、数的分合、凑十、0的意义、6和9的书写方向等核心概念错误较多\", \"4题跳过，开放题均未作答，Q15答案重复，表达和迁移能力弱\", \"多数题耗时0-4秒，疑似猜测，正确率趋势低\", \"专注与检查不足，未形成稳定解题流程\"]', '建议暂停高难度练习，先补10以内数感：数序、分与合、凑十、比较符号、0的意义、6和9书写；每题要求口述理由并限时检查；先完成再求快，减少跳题。', '[\"第1-2天：1-10数序、后一个/前一个数，10个10个数到100\", \"第3-4天：10以内数的分与合，重点8、7、6、5的分成\", \"第5-6天：凑十法，写出与2、6、5、7等凑成10的数\", \"第7天：比较大小与>、<开口方向，结合数轴练习\", \"第8天：0的意义、6和9书写方向、数字圈位置\", \"第9-10天：开放题口述/书面表达训练，每道题写理由并复查，减少跳题\"]', 'evaluated', '2026-09-20 22:25:43');
INSERT INTO `quiz_session` VALUES (219, 1532, '数学', 359, 1, '[137,148]', '专业', 18, 15, 10, 6, 5, 41, '{\"专注耐力\": 1, \"专业学习力\": 1, \"信息检索力\": 1, \"判断决策力\": 2, \"自律执行力\": 1, \"逻辑思维力\": 2}', '[\"能答对少量基础题，如10、20、30、40的数列识别、8分成3和5、6和4凑成10、大小符号开口方向等。\", \"对一致连续、一致收敛等个别判断有初步印象。\"]', '[\"基础概念混淆明显：数的作用、27读作七十二、计数规则、6和9的书写区分等出错。\", \"极限与一致连续的ε-δ、ε-N定义及证明题全部不会或跳过，专业知识严重不足。\", \"总耗时41秒且跳过5题，答题过快，缺少认真推导和书写过程。\", \"存在明显猜测作答痕迹，正确率低且不稳定。\"]', '先停止快速刷题和跳题，回归基础概念与定义抄写、复述和默写；每天固定时间学习数学，先掌握数数、读数、比较大小、分解等基础，再系统训练极限与一致连续的定义和证明。答题时必须写出关键步骤，减少跳过，做完后逐题订正。', '[\"第1周：复习数的认识、读数写数、大小比较、10以内分解与凑十，完成基础题并订正。\", \"第2周：抄写并背诵数列极限ε-N定义、函数极限ε-δ定义、连续定义，每天默写1遍。\", \"第3周：用定义证明简单极限，如lim(1/n)=0，逐步写出∀ε>0、取N、验证不等式全过程。\", \"第4周：学习一致连续与普通连续的区别，整理δ是否依赖点的典型例子，并做判断与证明题。\", \"每日要求：限时但不过快，至少完成5道题且不跳题；错题当天订正并记录错因。\"]', 'evaluated', '2026-09-20 23:14:07');
